    // # 2 = join (no unfinished tasks).
    // def _wait_ready(self, kind: int32, waker: Waker) -> bool:
    //     if kind == 0:
    //         if len(self._items) > 0:
    //             return True
    //         self._getters.append(waker)
    //         return False
    //     if kind == 1:
    //         if not self.full():
    //             return True
    //         self._putters.append(waker)
    //         return False
